import{_ as a,c as i,o as t,a2 as r}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"Z*L1NE","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/Z-L1NE.md","filePath":"entries/people/Z-L1NE.md"}'),n={name:"entries/people/Z-L1NE.md"};function o(s,e,l,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="z-l1ne" tabindex="-1">Z*L1NE <a class="header-anchor" href="#z-l1ne" aria-label="Permalink to &quot;Z*L1NE&quot;">​</a></h1><hr><p><strong>REAL NAME</strong>: Rosaline (commonly known as Rozz)<br><strong>BORN</strong>: c. 1981<br><strong>OCCUPATION</strong>: Activist, communications security specialist<br><strong>ORGANIZATION</strong>: The Bloc (co-founder, 1999)<br><strong>STATUS</strong>: Active</p><hr><p><strong>Z*L1NE</strong> (real name <strong>Rosaline</strong>, commonly known as <strong>Rozz</strong>) is an American activist and communications security specialist. She is best known as a co-founder of The Bloc, an organization that investigates and exposes alleged corporate misconduct by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a>&#39;s research facilities.</p><p><strong>At a glance</strong></p><ul><li>Co-founded The Bloc (1999) with associates known as <a href="./1NK">1NK</a> and <a href="./GUMM1">GUMM1</a></li><li>Co-authored <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999)</li><li>Infiltrated <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> communications networks</li><li>Hijacked facility broadcast to warn subjects of impending operations</li><li>Specializes in secure communications infiltration and signal intelligence</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Z<em>L1NE is one of three founding members of The Bloc, alongside <a href="./1NK">1NK</a> and <a href="./GUMM1">GUMM1</a>. The organization was formed in 1999 following the discovery of what the group alleges to be illegal research operations conducted by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a> at facilities near <a href="./../locations/Saint-Juniper">Saint Juniper</a>. Z</em>L1NE specializes in infiltrating secure communications systems and gained public attention for hijacking a research facility broadcast.</p><p>The Bloc is an underground activist organization that investigates alleged human experimentation programs, particularly those involving subjects designated with &quot;G-&quot; prefixes. The group came to prominence following the escape of Subject G-304 (known as &quot;<a href="./../subjects/G-BOY">G*BOY</a>&quot;) from the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>.</p><h2 id="early-life" tabindex="-1">Early life <a class="header-anchor" href="#early-life" aria-label="Permalink to &quot;Early life&quot;">​</a></h2><p>Rosaline grew up in Saint Juniper, California, and attended local schools through her junior year of high school. During this period, she was present when <a href="./Kai-Shepherd">Kai Shepherd</a> disappeared at <a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a> under unexplained circumstances (October 1995). The incident prompted her to conduct independent research into paranormal phenomena and unexplained disappearances at the <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a>, an occult bookshop operated by <a href="./Magdalena">Magdalena</a>.</p><h2 id="career-and-activism" tabindex="-1">Career and activism <a class="header-anchor" href="#career-and-activism" aria-label="Permalink to &quot;Career and activism&quot;">​</a></h2><h3 id="formation-of-the-bloc" tabindex="-1">Formation of The Bloc <a class="header-anchor" href="#formation-of-the-bloc" aria-label="Permalink to &quot;Formation of The Bloc&quot;">​</a></h3><p>At the <a href="./../locations/St-Juniper-Paranormal-Museum">paranormal museum</a>, Rosaline met two computer security researchers who used the aliases <a href="./1NK">1NK</a> and <a href="./GUMM1">GUMM1</a>. The pair claimed to have discovered evidence of unauthorized human research programs conducted by the Miter Corporation at facilities near <a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a>. In 1999, the three founded The Bloc, a watchdog organization dedicated to exposing corporate malfeasance in the research sector.</p><p>The group operated from basement facilities provided by <a href="./Magdalena">Magdalena</a> at the <a href="./../locations/St-Juniper-Paranormal-Museum">museum</a>. The founding members published their core document, <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion*, in 1999, outlining their philosophy of resistance against what they termed &quot;corporate cognitive manipulation.&quot;</p><h3 id="operations-and-public-actions" tabindex="-1">Operations and public actions <a class="header-anchor" href="#operations-and-public-actions" aria-label="Permalink to &quot;Operations and public actions&quot;">​</a></h3><p>The Bloc operated primarily through network security research and information gathering following its formation in 1999. Following the widely-reported escape of Subject G-304 (<a href="./../subjects/G-BOY">G*BOY</a>) from Saint Juniper Research Campus, Z*L1NE escalated the group&#39;s activities to include direct intervention.</p><p>She successfully hijacked a video transmission by Dr. Ravel, a senior researcher at the facility. Dr. Ravel had been addressing facility subjects about containment operations when Z*L1NE interrupted the broadcast to deliver a warning. The incident demonstrated The Bloc&#39;s capabilities in penetrating secure institutional communications.</p><h3 id="technical-expertise" tabindex="-1">Technical expertise <a class="header-anchor" href="#technical-expertise" aria-label="Permalink to &quot;Technical expertise&quot;">​</a></h3><p>Z*L1NE specializes in infiltrating secure communications systems. When The Bloc gained unauthorized access to sj-securelab.net—a private network operated by the research campus—she was responsible for breaching the operational messaging layer. Within The Bloc&#39;s organizational structure, she functions as the primary communications security specialist.</p><h2 id="personal-life" tabindex="-1">Personal life <a class="header-anchor" href="#personal-life" aria-label="Permalink to &quot;Personal life&quot;">​</a></h2><p>Z*L1NE resides in Saint Juniper with a domestic partner who is reportedly aware of her activist work. She maintains her involvement with The Bloc while living under her legal name in the community.</p><h2 id="controversies" tabindex="-1">Controversies <a class="header-anchor" href="#controversies" aria-label="Permalink to &quot;Controversies&quot;">​</a></h2><h3 id="volunteer-infiltration-operation" tabindex="-1">Volunteer infiltration operation <a class="header-anchor" href="#volunteer-infiltration-operation" aria-label="Permalink to &quot;Volunteer infiltration operation&quot;">​</a></h3><p>In the early 2000s, The Bloc organized an operation in which volunteers attempted to infiltrate Miter facilities by allowing themselves to be recruited as research subjects. The operation was intended to gather intelligence from inside the facilities. However, the operation failed when the volunteers lost contact with the organization and did not return with intelligence as planned. The fate of these volunteers remains disputed, with The Bloc claiming the individuals underwent memory erasure procedures.</p><h3 id="allegations-of-harassment" tabindex="-1">Allegations of harassment <a class="header-anchor" href="#allegations-of-harassment" aria-label="Permalink to &quot;Allegations of harassment&quot;">​</a></h3><p>The Bloc has claimed that Z*L1NE was targeted with psychological deterrence measures while conducting online research. The group alleged that unidentified parties attempted to dissuade her from investigative activities through direct messaging. No law enforcement investigation was opened, and the claims remain unverified.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./1NK">1NK</a></li><li><a href="./GUMM1">GUMM1</a></li><li><a href="./Magdalena">Magdalena</a></li><li><a href="./Kai-Shepherd">Kai Shepherd</a></li><li><a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a></li><li><a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a></li><li><a href="./../organizations/The-Bloc">The Bloc</a></li><li><a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999) — Founding document co-authored by 1NK, Z-L1N3, and GUMM1</li><li>Regional news coverage of Saint Juniper Research Campus security breach (early 2000s)</li><li>&quot;The Bloc: Saint Juniper&#39;s Paranormal Activists,&quot; coverage of activist organization</li><li>Public broadcast interruption incident, Saint Juniper Research Campus</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',34)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
